<?php if(!defined('APP_ENTRY'))exit; if($_SERVER['REQUEST_METHOD']==='POST')try { $username=username_field(); $password=password_field(); $code=trim(post('code')); if(!preg_match('/^[a-f0-9]{32}$/D',$code))throw new DomainException('Invalid or expired activation code.'); transaction(function()use($username,$password,$code){ $s=one('SELECT id FROM students WHERE invite_hash=? AND invite_expires>NOW() FOR UPDATE',[hash('sha256',$code)]); if(!$s)throw new DomainException('Invalid or expired activation code.'); execute('INSERT INTO student_accounts(student_id,username,password_hash) VALUES(?,?,?)',[$s['id'],$username,password_hash($password,PASSWORD_DEFAULT)]); execute('UPDATE students SET invite_hash=NULL,invite_expires=NULL WHERE id=?',[$s['id']]); }); flash('Account activated. Sign in as a student.'); redirect('login'); }catch(DomainException $ex){$error=$ex->getMessage();}catch(PDOException $ex){error_log_file($ex);$error='Username is already in use or account could not be activated.';} ?>
<p class="muted">Ask the administrator for your personal one-time activation code. This prevents someone else from claiming your student record.</p><?php if($error):?><div class="error"><?=e($error)?></div><?php endif;?><form method="post"><?=csrf_field()?><label>Activation code<input name="code" required maxlength="32" value="<?=val('code')?>"></label><label>Username<input name="username" required maxlength="50" value="<?=val('username')?>"></label><label>Password (at least 10 characters)<input type="password" name="password" required minlength="10" maxlength="72"></label><button>Activate account</button></form><p class="spaced"><a href="<?=e(url('login'))?>">Back to sign in</a></p>
